fn main() -> tryte:
    mut x: i64 = 3
    x = x + 4
    return to_tryte(x)

fn sum4(a: i64, b: i64, c: i64, d: i64) -> i64:
    return a + b + c + d

fn main() -> tryte:
    return to_tryte(sum4(1, 1, 2, 3))

fn main() -> tryte:
    mut x: i64 = 0
    while x < 3:
        x += 1
    return to_tryte(x)

fn main() -> tryte:
    mut values: i64[2] = [2, 5]
    values[0] = values[0] + values[1]
    return to_tryte(values[0])

fn inc(x: i64) -> i64:
    return x + 1

fn main() -> tryte:
    return to_tryte(inc(inc(5)))
